import { test, expect } from '@playwright/test';
import { setLanguage } from './plans-helpers';
import { accountRows, loadedRowCount, openPlansTabNamed, searchBox, EMPTY_HE } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Search with no match shows empty-state message in Hebrew #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'he');
    await openPlansTabNamed(page, 'חבילות');
    await loadedRowCount(page);

    await searchBox(page).fill('zzqqxx-none');
    await expect(page.getByText(EMPTY_HE, { exact: true })).toBeVisible();
    await expect(accountRows(page)).toHaveCount(0);
  });
});
